#!/bin/sh
# Generates the bitmap fonts in main/ui/fonts/ from the TTFs beside this script
# (docs/firmware-design.md, section 7). The generated files are committed, so neither the firmware
# build nor sim/ needs Node. Runs in the frontend sidecar:
#
#   cexec frontend tools/fonts/generate.sh
#
# A slice that needs another size adds a line at the bottom; another icon, a line in icons.txt.

set -e

cd "$(dirname "$0")"

OUT=../../main/ui/fonts
CONV="npx --yes lv_font_conv@1.5.3"

# Latin script with accents: Basic Latin, Latin-1 Supplement, Latin Extended-A, and typographic
# punctuation (dashes, quotes, bullet, ellipsis, euro).
TEXT_RANGES=0x20-0x7E,0xA0-0xFF,0x100-0x17F,0x2013-0x2014,0x2018-0x201D,0x2022,0x2026,0x20AC

ICON_RANGES=$(grep -v '^#' icons.txt | awk 'NF == 2 { printf "%s0x%s", sep, $2; sep = "," }')

text_font() {
    name=$1
    face=$2
    size=$3

    echo "$name"
    $CONV --font "$face" --size "$size" --bpp 4 --no-compress --format lvgl --range "$TEXT_RANGES" \
        --lv-include lvgl.h --lv-font-name "$name" -o "$OUT/$name.c"
}

icon_font() {
    name=$1
    size=$2

    echo "$name"
    $CONV --font materialdesignicons-webfont.ttf --size "$size" --bpp 4 --no-compress --format lvgl \
        --range "$ICON_RANGES" --lv-include lvgl.h --lv-font-name "$name" -o "$OUT/$name.c"
}

icons_header() {
    echo icons.h
    node -e '
const fs = require("fs");
const lines = fs.readFileSync("icons.txt", "utf8").split("\n").filter((l) => l.trim() && !l.startsWith("#"));
let out = "#pragma once\n\n// Generated by tools/fonts/generate.sh from tools/fonts/icons.txt. Do not edit.\n//\n";
out += "// Each icon is a UTF-8 string to draw with an icons_* font.\n\n";
for (const line of lines) {
    const [name, hex] = line.trim().split(/\s+/);
    const bytes = Buffer.from(String.fromCodePoint(parseInt(hex, 16)), "utf8");
    const escaped = [...bytes].map((b) => "\\x" + b.toString(16).toUpperCase().padStart(2, "0")).join("");
    out += `#define ICON_${name.toUpperCase()} "${escaped}"  // U+${hex.toUpperCase()}\n`;
}
fs.writeFileSync(process.argv[1], out);
' "$OUT/icons.h"
}

mkdir -p "$OUT"

text_font font_regular_24 Roboto-Regular.ttf 24
text_font font_regular_32 Roboto-Regular.ttf 32
text_font font_medium_32 Roboto-Medium.ttf 32
text_font font_medium_40 Roboto-Medium.ttf 40

icon_font icons_40 40
icon_font icons_64 64

icons_header
